import{_ as o,o as r,c as d,a2 as a}from"./chunks/framework.DGvnA5EY.js";const n="/workbuddy-guide/assets/02-chatbot-vs-agent.D0Ox530-.png",e="/workbuddy-guide/assets/01-official-sidebar.si-lsnLi.png",k=JSON.parse('{"title":"第 1 章 初识 WorkBuddy","description":"> 内容来源：WorkBuddy 官方指南（非官方整理，© 本指南作者，保留所有权利） 你大概听过\\"AI 助手\\"很多次，但 WorkBuddy 不太一样：它不是让你去学提示词， 而是给你一个能直接干活的工作台。这一章用大白话讲清楚它到底是什么、 能帮你做什么、以及你该用什么样的预期去用它。","frontmatter":{"title":"第 1 章 初识 WorkBuddy"},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 1 章 初识 WorkBuddy/index.md","filePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 1 章 初识 WorkBuddy/index.md","lastUpdated":1791629861000}'),s={name:"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 1 章 初识 WorkBuddy/index.md"};function u(l,t,i,g,p,h){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="第-1-章-初识-workbuddy" tabindex="-1">第 1 章 初识 WorkBuddy <a class="header-anchor" href="#第-1-章-初识-workbuddy" aria-label="Permalink to &quot;第 1 章 初识 WorkBuddy&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南（非官方整理，© 本指南作者，保留所有权利）</p></blockquote><p>你大概听过&quot;AI 助手&quot;很多次，但 WorkBuddy 不太一样：它不是让你去学提示词， 而是给你一个<strong>能直接干活的工作台</strong>。这一章用大白话讲清楚它到底是什么、 能帮你做什么、以及你该用什么样的预期去用它。</p><h2 id="一、一句话说清-workbuddy-是什么" tabindex="-1">一、一句话说清 WorkBuddy 是什么 <a class="header-anchor" href="#一、一句话说清-workbuddy-是什么" aria-label="Permalink to &quot;一、一句话说清 WorkBuddy 是什么&quot;">​</a></h2><p>WorkBuddy 是一个 <strong>AI Agent（智能体）办公工作台</strong>：你用自然语言下任务， 它自己拆步骤、调工具、出结果。常见工具包括写代码、读文件、上网查资料、 连外部服务（邮箱、文档、数据库等）。</p><p><strong>和&quot;聊天机器人&quot;的区别</strong>：聊天机器人主要陪你聊；WorkBuddy 能<strong>动手</strong>—— 改文件、跑脚本、发邮件、生成文档，并把结果落到你的电脑或云端。</p><p><img src="'+n+'" alt="左边只能说，右边会动手：WorkBuddy 自己拆步骤，把文档表格 PPT 搬进文件夹" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解两者的区别，与实际软件界面无关。</em></p><h2 id="二、它能帮你做的-4-类事" tabindex="-1">二、它能帮你做的 4 类事 <a class="header-anchor" href="#二、它能帮你做的-4-类事" aria-label="Permalink to &quot;二、它能帮你做的 4 类事&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>举例</th><th>你得到的</th></tr></thead><tbody><tr><td>写东西</td><td>写周报、改文案、出方案</td><td>一份可直接用的文档</td></tr><tr><td>处理文件</td><td>整理桌面、批量重命名、提取表格</td><td>干净的文件系统 / Excel</td></tr><tr><td>联网办事</td><td>查资料、盯资讯、填表单</td><td>汇总好的信息或已完成的动作</td></tr><tr><td>自动跑</td><td>每周一发周报、每天抓新闻</td><td>不用你操心，到点出活</td></tr></tbody></table><h2 id="三、第一次打开-你会看到什么" tabindex="-1">三、第一次打开，你会看到什么 <a class="header-anchor" href="#三、第一次打开-你会看到什么" aria-label="Permalink to &quot;三、第一次打开，你会看到什么&quot;">​</a></h2><p>WorkBuddy 的工作界面主要由四个区域组成：<strong>顶部工具栏</strong>（关于、编辑、窗口等 常用操作入口）、<strong>左侧边栏</strong>（任务列表，按文件夹分组，底部是用户头像）、 <strong>中间对话区</strong>（核心交互区，含任务标题栏、消息列表和输入框）、<strong>右侧结果区</strong> （提供概览与产物两类内容，可在同一区域切换查看）。</p><p><img src="'+e+'" alt="官方界面标注了侧边栏、对话区和结果区三个区域" loading="lazy"></p><p><em>此图片来自官方。</em></p><p>你大部分时间都在&quot;新建任务 → 描述需求 → 看它执行 → 收结果&quot;这个循环里。 <strong>侧边栏、对话区、结果区</strong>这三个词后面会反复出现，先记住它们各自管什么：</p><table tabindex="0"><thead><tr><th>区域</th><th>你在里面做什么</th></tr></thead><tbody><tr><td>侧边栏</td><td>找以前的任务、管理工作空间</td></tr><tr><td>对话区</td><td>提需求、看它干活、追问补充</td></tr><tr><td>结果区</td><td>收文件、看改动、预览网页</td></tr></tbody></table><h2 id="四、新手最常见的-3-个预期误区" tabindex="-1">四、新手最常见的 3 个预期误区 <a class="header-anchor" href="#四、新手最常见的-3-个预期误区" aria-label="Permalink to &quot;四、新手最常见的 3 个预期误区&quot;">​</a></h2><ol><li><strong>&quot;它什么都能做&quot;</strong> —— 不能。它擅长有明确输入输出、能拆步骤的任务； 纯创意拍板、需要真人担责的事，它只能辅助。</li><li><strong>&quot;说一句就行&quot;</strong> —— 说清楚&quot;要什么 + 给什么 + 交付成什么样&quot;三要素，结果才好。</li><li><strong>&quot;出错就废了&quot;</strong> —— 它可以回滚、重试、分步确认；把大任务拆小，风险可控。</li></ol><h2 id="五、本章任务清单-做完就算过关" tabindex="-1">五、本章任务清单（做完就算过关） <a class="header-anchor" href="#五、本章任务清单-做完就算过关" aria-label="Permalink to &quot;五、本章任务清单（做完就算过关）&quot;">​</a></h2><ul><li>[ ] 能用自己的话解释 WorkBuddy 和聊天机器人的区别</li><li>[ ] 想好你第一个想让它帮你做的任务是什么</li><li>[ ] 打开软件，认出左侧导航栏、对话区、结果区三个区域</li></ul><hr><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p>这一章出现了几个容易卡住的词，这里补一句人话解释，看不懂可以跳过正文直接看这里。</p></blockquote><p><strong>AI Agent（智能体）</strong> &quot;代理&quot;的意思是<strong>替你去做事</strong>。普通 AI 聊天工具是&quot;你问它答&quot;，Agent 是 &quot;你交任务，它自己拆步骤、去执行、给你结果&quot;。区别在于它会<strong>主动调用工具</strong> ——读文件、跑代码、连网、操作你的电脑，而不只是输出文字。</p><p><strong>工作台</strong> 这里指一个<strong>装在电脑上、能真正碰到你文件的软件</strong>。不是网页版那种 关掉就没了的东西，你的文件处理都在本地完成。</p><p><strong>自然语言</strong> 就是<strong>人话</strong>。你不需要学什么专业指令或代码语法，用平时说话的方式交代任务就行。</p><p><strong>提示词（Prompt）</strong> 你给 AI 的那段话。说得越具体（要什么、给什么、交付成什么），它越不容易猜错。 但 WorkBuddy 的思路是<strong>你把目标讲清就行，不用自己拆步骤</strong>。</p><p><strong>工具调用（Tool Call）</strong> AI 自己&quot;伸手&quot;去操作外部东西的动作。比如打开一个 Excel 文件、读一个网页、 跑一段脚本。这个过程你能看到，它会一步一步打出来告诉你。</p><p><strong>结果区 / 产物</strong> &quot;产物&quot;就是它做完之后<strong>交付给你的东西</strong>：文档、表格、PPT、报告、图片。 &quot;结果区&quot;是放这些东西的地方，在界面右侧。</p><p><strong>云端</strong> 指网络上的服务器。&quot;结果落到云端&quot;就是把文件传到网上，换台电脑也能打开。 WorkBuddy 支持传到云端网盘、腾讯文档等地方。</p><p><strong>回滚</strong><strong>撤销、恢复到之前的版本</strong>。它改错了可以退回去，不用担心一错到底。 做重要文件的任务时，这个能力很关键。</p><p><strong>预期误区</strong> 指新手容易想错的地方。比如以为&quot;它什么都能做&quot;就是一种典型误区—— 提前知道这些坑，能少走很多弯路。</p><hr><p><em>下一篇：第 2 章 下载、安装、登录与更新——把它装到你的电脑上。</em></p>',34)])])}const b=o(s,[["render",u]]);export{k as __pageData,b as default};
